import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    counted_kinds = ['counted']
    df_counted = df[df['row_kind'].isin(counted_kinds)].copy()

    claim_line_cols = ['Claim ID', 'Line No']
    df_counted['_version'] = df_counted['Adjustment Seq']
    df_counted = df_counted.sort_values(claim_line_cols + ['_version'])
    df_counted = df_counted.drop_duplicates(subset=claim_line_cols, keep='last')

    df_counted = df_counted[~df_counted['Claim Status'].str.lower().isin(
        ['void', 'voided', 'cancelled', 'canceled', 'reversed']
    )]

    top_n = 10

    cpt_paid = (
        df_counted.groupby('CPT/HCPCS')['Paid Amount']
        .sum()
        .reset_index()
        .sort_values('Paid Amount', ascending=False)
    )
    top_cpt = cpt_paid.head(top_n)

    result['segments'].append({
        "segment_column": "CPT/HCPCS",
        "metric_column": "Paid Amount",
        "aggregation": "sum",
        "label": "total_paid_by_procedure",
        "results": [
            {"name": str(row['CPT/HCPCS']), "value": float(row['Paid Amount'])}
            for _, row in top_cpt.iterrows()
        ]
    })

    cpt_count = (
        df_counted.groupby('CPT/HCPCS')['Claim ID']
        .nunique()
        .reset_index()
        .rename(columns={'Claim ID': 'claim_count'})
        .sort_values('claim_count', ascending=False)
    )
    top_cpt_count = cpt_count.head(top_n)

    result['segments'].append({
        "segment_column": "CPT/HCPCS",
        "metric_column": "Claim ID",
        "aggregation": "count",
        "label": "claim_count_by_procedure",
        "results": [
            {"name": str(row['CPT/HCPCS']), "value": float(row['claim_count'])}
            for _, row in top_cpt_count.iterrows()
        ]
    })

    cpt_avg = (
        df_counted.groupby('CPT/HCPCS')['Paid Amount']
        .mean()
        .reset_index()
        .sort_values('Paid Amount', ascending=False)
    )
    top_cpt_avg = cpt_avg.head(top_n)

    result['segments'].append({
        "segment_column": "CPT/HCPCS",
        "metric_column": "Paid Amount",
        "aggregation": "mean",
        "label": "avg_paid_by_procedure",
        "results": [
            {"name": str(row['CPT/HCPCS']), "value": float(row['Paid Amount'])}
            for _, row in top_cpt_avg.iterrows()
        ]
    })

    total_paid = df_counted['Paid Amount'].sum()
    cpt_paid_ratio = cpt_paid.copy()
    cpt_paid_ratio['ratio'] = cpt_paid_ratio['Paid Amount'] / total_paid if total_paid > 0 else 0.0
    top_cpt_ratio = cpt_paid_ratio.head(top_n)

    result['segments'].append({
        "segment_column": "CPT/HCPCS",
        "metric_column": "Paid Amount",
        "aggregation": "ratio",
        "label": "paid_share_by_procedure",
        "results": [
            {"name": str(row['CPT/HCPCS']), "value": float(row['ratio'])}
            for _, row in top_cpt_ratio.iterrows()
        ]
    })

    result['assumptions'].append(
        "Only 'counted' row_kind rows used; last version per claim+line kept; voided statuses excluded."
    )
    result['assumptions'].append(
        "Top 10 CPT/HCPCS codes shown by total paid amount; claim count uses distinct Claim IDs."
    )
    result['assumptions'].append(
        "paid_share_by_procedure is each procedure's share of total paid across all counted lines."
    )

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

